export interface UserDAO {
  find(id: number): Promise<User | null>;
}

type Store = 'postgres' | 'sqlite';

const registry: Record<Store, (cfg: Config) => UserDAO> = {
  postgres: (cfg) => new PgUserDAO(cfg.pool),
  sqlite:   (cfg) => new SqliteUserDAO(cfg.path),
};

export function userDAO(store: Store, cfg: Config): UserDAO {
  const make = registry[store];          // Store has no other keys
  if (!make) throw new Error(`unknown store: ${store}`);
  return make(cfg);
}

