export const USER_DAO = Symbol('USER_DAO');

@Module({
  providers: [
    {
      provide: USER_DAO,
      useFactory: (cfg: StoreConfig, pg: PgClient, sqlite: SqliteClient): UserDAO =>
        cfg.store === 'postgres' ? new PgUserDAO(pg) : new SqliteUserDAO(sqlite),
      inject: [StoreConfig, PgClient, SqliteClient],
    },
  ],
  exports: [USER_DAO],
})
export class PersistenceModule {}
